sys_script_include.script:
function GetStoreAppRecord(vStoreApp)
{
	var grStoreApp = GetRecord('sys_store_app',vStoreApp);
	if (IsValidRecord(grStoreApp) == true)
	{
		return true;
	}
	var strStoreApp = GetStringValue(vStoreApp);
	if (IsValidScope(strStoreApp) == true)
	{
		grStoreApp = RecordQuery(
			'sys_store_app',
			{
				scope: strStoreApp
			});
		if (IsValidRecord(grStoreApp) == true)
		{
			return grStoreApp;
		}
	}
	return false;
}
